#
# Structure for table "distribuicao_locais_setor"
#

DROP TABLE IF EXISTS `distribuicao_locais_setor`;
CREATE TABLE `distribuicao_locais_setor` (
  `produto` int(11) NOT NULL DEFAULT 0,
  `setor` int(11) NOT NULL DEFAULT 0,
  `unidade_medida` varchar(255) DEFAULT 'UND',
  `quantidade` varchar(255) NOT NULL DEFAULT '0',
  `local` int(11) NOT NULL DEFAULT 0,
  `data_cadastro` date NOT NULL DEFAULT '2000-01-01',
  `data_recadastro` datetime NOT NULL DEFAULT '2000-01-01 00:00:00'
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

#
# Data for table "distribuicao_locais_setor"
#


#
# Structure for table "forma_pagamento"
#

DROP TABLE IF EXISTS `forma_pagamento`;
CREATE TABLE `forma_pagamento` (
  `codigo` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `id` int(10) unsigned NOT NULL DEFAULT 0,
  `descricao` text NOT NULL,
  `desc_maximo` int(11) DEFAULT 0,
  `parcelas` int(11) DEFAULT 0,
  `intervalo` int(11) DEFAULT 0,
  `recebimento` int(11) DEFAULT 0,
  `data_cadastro` date NOT NULL DEFAULT '2000-01-01',
  `data_recadastro` datetime NOT NULL DEFAULT '2000-01-01 00:00:00',
  `ativo` char(1) NOT NULL DEFAULT 'S',
  PRIMARY KEY (`codigo`)
